/* ---------- board chrome ---------- */
let BN = 0;
const board = (title, kicker, lead, body, opt = {}) => { BN++; const n = String(BN).padStart(2, "0");
  return `<section lang="en" class="board t" data-theme="${opt.theme || "light"}" id="b${n}"><header class="bh"><div class="row g3"><div class="logo">${I("groups")}</div><div><b class="bw">ADIAK</b><span class="cap">Design System 1.0</span></div></div><span class="over">Visual specification · ${n}</span></header>
  <div class="bt"><div><span class="over">${n} / ${kicker}</span><h1 class="bigt">${title}</h1><p class="sec lead">${lead}</p></div>${opt.aside ? `<div class="aside sup">${opt.aside}</div>` : ""}</div>${body}
  <footer class="bf cap"><span>ADIAK 1.0 · ${title}</span><span>Monochrome · Inter · 1.8 px outline icons</span></footer></section>`; };
const panel = (label, html, cls = "") => `<div class="pn ${cls}"><div class="pnl over">${label}</div>${html}</div>`;
const split = f => `<div class="split"><div class="half" data-theme="light"><div class="hl over">Light</div>${f("light")}</div><div class="half" data-theme="dark"><div class="hl over">Dark</div>${f("dark")}</div></div>`;

/* =============== 00 · CRITIQUE =============== */
const CRIT = [
 ["Palette", "The live app is not monochrome: indigo accent (#4338CA/#6366F1), blurred indigo blobs on login, indigo/violet background pattern, green/amber/blue chips, gold/silver/bronze gradient podium, hue-coded avatars and groups, indigo admin sidebar (#312E81), red badges, green unread counters, amber offline banner, a purple-heart emoji in UI copy. The PDF presented this as already monochrome — it is not.", "Every colour → official tokens; state = contrast, weight, border style, icon."],
 ["Tokens", "PDF defined colours only as swatches with no roles (button, nav, badge, overlay), so the same grey meant different things on different boards.", "Role-based official tokens; one alias layer; nothing hard-coded."],
 ["Contrast", "PDF used #999 for labels and table headers. #999 on #FFF = 2.85:1 (fails WCAG AA text).", "--text-muted only for placeholders, disabled, timestamps; essential text uses --text-secondary (5.74:1)."],
 ["Type", "Ranges instead of values (28–32 px, 'Inter · consistent weights'); 800 weights in the app; the PDF type card overlapped neighbouring cards.", "Fixed scale: 30/22/17/15/14/13/12, weights 400/500/600 (700 only for counters/wordmark)."],
 ["Geometry", "'Buttons 8–10 px, cards 12–16 px' as ranges; app mixes 9/10/12/13/14/16/18 px radii and 34–58 px control heights.", "Control 10, card 14, dialog 16, pill; heights 32/40/44."],
 ["States", "Only default/disabled shown. No hover, focus, active, error, loading; dark focus ring missing.", "Full state matrix per component, both themes; 2 px ink focus ring + 2 px offset."],
 ["Destructive & error", "Red relied on for errors/deletes; colour-only meaning fails colour-blind users.", "Monochrome: alert icon + 1.5 px ink border + explicit verb + confirmation dialog."],
 ["Icons", "Settings glyph ≈ Sun glyph (theme toggle sits next to it); Chats and Feedback share one icon in admin; ⏻ ⇄ ← glyphs and ~70 emoji used as UI icons (medals, file types, toasts).", "SVG only, 1.8 stroke, currentColor; new sliders/back/swap/alert glyphs; emoji stay only as user content."],
 ["Navigation", "PDF invented a 'Tələbələr' student-nav item and 'Parametrlər'; labels mixed ('Əsas' vs 'Ana səhifə', 'Müraciət' vs 'Müraciətlər').", "Real nav only: Ana səhifə · Qruplar · Çat · Müraciətlər və qrupsuzlar · Bildirişlər · Alətlər · Ayarlar."],
 ["Mobile", "Phones drawn without status/gesture bars, no keyboard state, chat with a floating search instead of the real composer.", "Safe-area strips in --background, 64 px tab bar, composer pinned above keyboard, tab bar hidden while typing."],
 ["Dark theme", "Dark boards inverted light ones (pure white buttons on #111 everywhere, unlayered cards).", "Stepped surfaces #111 → #1A1A1A → #262626; borders carry elevation; shadows only on overlays."],
 ["Fidelity", "Showcase screens cropped mid-component (text overflowing cards, cut-off buttons on 04/05/06).", "Every screen rendered whole at real size (1280×800, 390×844) then scaled."]
];
const b00 = () => board("Design review", "Critique of the v0 PDF and the live app", "What was wrong, why it matters, and the rule that replaces it. Verified against the repository (CSS, JS, i18n) — not assumed.",
 `<div class="crit">${CRIT.map(([k, a, b], i) => `<div class="ci"><div class="cnum num">${String(i + 1).padStart(2, "0")}</div><div><div class="h3">${k}</div><p class="sm sec">${a}</p><p class="sm fix">${I("check", "i16")}<span>${b}</span></p></div></div>`).join("")}</div>`,
 { aside: "Verified = read from code.<br>Proposed = DS 1.0 change, needs approval." });

/* =============== 01 · FOUNDATIONS =============== */
const TOK = [["--background", "#FFFFFF", "#111111", "Page canvas"], ["--background-secondary", "#F7F7F7", "#161616", "Chat well, disabled field"], ["--surface", "#FFFFFF", "#1A1A1A", "Cards, sidebar, bars"], ["--surface-secondary", "#FAFAFA", "#202020", "Hover rows, table head"], ["--surface-elevated", "#F0F0F0", "#262626", "Secondary btn, selected, menus"], ["--text-primary", "#111111", "#FFFFFF", "Body, titles, icons"], ["--text-secondary", "#666666", "#A3A3A3", "Labels, supporting copy"], ["--text-muted", "#999999", "#737373", "Placeholder, time, disabled"], ["--border", "#E8E8E8", "#333333", "Dividers, card edges"], ["--border-strong", "#D4D4D4", "#444444", "Inputs, outline buttons"], ["--button-primary", "#111111", "#FFFFFF", "Primary action, own bubble"], ["--button-primary-text", "#FFFFFF", "#111111", "Text on primary"], ["--button-hover", "#2A2A2A", "#E5E5E5", "Primary hover"], ["--navigation-active", "#111111", "#FFFFFF", "Active nav item"], ["--navigation-active-text", "#FFFFFF", "#111111", "Text on active nav"], ["--badge-background", "#EEEEEE", "#2A2A2A", "Neutral badge"], ["--badge-text", "#111111", "#FFFFFF", "Badge label"], ["--overlay", "rgba(0,0,0,.45)", "rgba(0,0,0,.65)", "Modal scrim"]];
const lum = h => { if (!h.startsWith("#")) return null; const c = [1, 3, 5].map(i => parseInt(h.substr(i, 2), 16) / 255).map(v => v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4)); return .2126 * c[0] + .7152 * c[1] + .0722 * c[2]; };
const cr = (a, b) => { const x = lum(a), y = lum(b); return ((Math.max(x, y) + .05) / (Math.min(x, y) + .05)).toFixed(2); };
const tokTable = th => `<table class="tok"><tr><th></th><th>Token</th><th>Value</th><th>Role</th></tr>${TOK.map(([n, l, d, r]) => { const v = th === "light" ? l : d; return `<tr><td><i class="sw" style="background:var(${n})"></i></td><td class="mono">${n}</td><td class="mono sec">${v}</td><td class="sec">${r}</td></tr>`; }).join("")}</table>`;
const CONTRAST = [["--text-primary", "--surface", "#111111", "#FFFFFF", "#FFFFFF", "#1A1A1A"], ["--text-secondary", "--surface", "#666666", "#FFFFFF", "#A3A3A3", "#1A1A1A"], ["--text-muted", "--surface", "#999999", "#FFFFFF", "#737373", "#1A1A1A"], ["--button-primary-text", "--button-primary", "#FFFFFF", "#111111", "#111111", "#FFFFFF"], ["--text-secondary", "--surface-elevated", "#666666", "#F0F0F0", "#A3A3A3", "#262626"], ["--border-strong", "--surface", "#D4D4D4", "#FFFFFF", "#444444", "#1A1A1A"]];
const b01 = () => board("Foundations", "Colour · type · space · shape", "Official tokens only. Two themes, one role map. Dark is layered (canvas → surface → elevated), not inverted.",
 `<div class="grid f01">
  ${panel("Colour tokens · light", tokTable("light"), "lt")}
  <div class="pn dk" data-theme="dark"><div class="pnl over">Colour tokens · dark</div>${tokTable("dark")}</div>
  <div class="col g4">
   ${panel("Contrast (WCAG 2.2)", `<table class="tok ctr"><tr><th>Pair</th><th>Light</th><th>Dark</th></tr>${CONTRAST.map(([a, b, l1, l2, d1, d2]) => { const L = cr(l1, l2), D = cr(d1, d2), ok = v => v >= 4.5 ? "AA" : v >= 3 ? "AA large / UI" : "decorative"; return `<tr><td class="mono">${a.replace("--", "")}<br><span class="mut">on ${b.replace("--", "")}</span></td><td class="num"><b>${L}</b> <span class="cap">${ok(L)}</span></td><td class="num"><b>${D}</b> <span class="cap">${ok(D)}</span></td></tr>`; }).join("")}</table><p class="cap" style="margin-top:8px">Rule: --text-muted never carries essential information. Input borders (--border-strong) are paired with a label and placeholder so the field is identifiable without the edge alone.</p>`)}
   ${panel("Type · Inter (self-hosted, latin + latin-ext: Ə ə Ğ ğ Ş ş İ ı Ç ç Ö ö Ü ü)", `<div class="ts">
    <div><span class="h1">Ana səhifə</span><span class="cap mono">H1 · 30/36 · 600 · −2%</span></div>
    <div><span class="h2">Sinif reytinqi</span><span class="cap mono">H2 · 22/28 · 600 · −1.5%</span></div>
    <div><span class="h3">Qoşulma müraciəti</span><span class="cap mono">H3 · 17/24 · 600</span></div>
    <div><span class="body">Bir qrupu açıb qoşulma müraciəti göndərin.</span><span class="cap mono">Body · 15/22 · 400</span></div>
    <div><span class="sm">Xal vermək və qrupları idarə etmək</span><span class="cap mono">Body S · 14/20 · 400–500</span></div>
    <div><span class="sup">Ustad rütbəsinə 16 xal qalıb</span><span class="cap mono">Support · 13/18 · 400</span></div>
    <div><span class="cap">08:14 · redaktə edilib</span><span class="cap mono">Caption · 12/16 · 400–500</span></div>
    <div><span class="over">Liderlər</span><span class="cap mono">Overline · 12/16 · 600 · +8% · caps</span></div></div>`)}
  </div>
  <div class="col g4">
   ${panel("Spacing · 4 px base", `<div class="spc">${[4, 8, 12, 16, 24, 32, 48].map(v => `<div><i style="width:${v}px;height:${v}px"></i><span class="cap num">${v}</span></div>`).join("")}</div><p class="cap">Card padding 16 (20 large) · section gap 24 · page gutter 24 desktop / 16 phone · list row 12 · inline icon gap 8.</p>`)}
   ${panel("Radius", `<div class="rad">${[["6", "checkbox · kbd"], ["10", "button · input · nav"], ["14", "card · panel"], ["16", "dialog · sheet"], ["999", "badge · avatar"]].map(([r, l]) => `<div><i style="border-radius:${Math.min(+r, 28)}px"></i><b class="num">${r}</b><span class="cap">${l}</span></div>`).join("")}</div>`)}
   ${panel("Border & elevation", `<div class="elev"><div class="card flat">1 px --border<br><span class="cap">resting card</span></div><div class="card" style="box-shadow:var(--shadow-2)">shadow-2<br><span class="cap">menu · toast</span></div><div class="card" style="box-shadow:var(--shadow-3)">shadow-3<br><span class="cap">dialog · sheet</span></div></div><p class="cap">Dark: elevation = lighter surface (#1A1A1A → #262626) + --border-strong; shadows only on overlays.</p>`)}
   ${panel("Breakpoints (match current CSS)", `<table class="tok"><tr><td class="mono">≤ 380</td><td class="sec">Compact phone · 2-col tiles, 12 px gutters</td></tr><tr><td class="mono">≤ 800</td><td class="sec">Phone · tab bar 64 px, sheets, full-screen chat</td></tr><tr><td class="mono">801–1100</td><td class="sec">Compact desktop · sidebar 220</td></tr><tr><td class="mono">1101–1399</td><td class="sec">Desktop · sidebar 248, content ≤ 1240</td></tr><tr><td class="mono">≥ 1400</td><td class="sec">Wide · sidebar 280, content ≤ 1480</td></tr><tr><td class="mono">admin ≤ 900</td><td class="sec">Sidebar → top bar, horizontal nav</td></tr></table>`)}
  </div></div>`);

/* =============== 02 · ICONOGRAPHY =============== */
const EMOJI = [["🥇 🥈 🥉", "medal", "Podium / medals"], ["🏆", "trophy", "Leaders"], ["🚫", "ban", "Deleted message"], ["📎", "clip", "File preview"], ["🖼️", "image", "Photo preview"], ["🎤", "mic", "Voice preview"], ["🎭", "smile", "Sticker preview"], ["🗳️", "vote", "Vote"], ["⏻", "logout", "Log out"], ["⇄", "swap", "Switch class"], ["←", "back", "Back"], ["✕ ✖", "x", "Close"], ["✓ ✅", "check", "Done / accepted"], ["🌱 🚀 🤝", "sprout", "Badge art → one icon per badge"], ["🎉 ✨ ♡", "—", "Remove from UI copy (incl. a purple heart)"]];
const b02 = () => { const keys = Object.keys(typeof ICONS !== "undefined" ? ICONS : {});
 return board("Iconography", "Existing SVG set · rules · fixes", "The current inline set (icons.js, " + keys.length + " glyphs) already follows the rule: 24 × 24 grid, 1.8 px stroke, round caps & joins, currentColor. DS 1.0 keeps every existing glyph, fixes two collisions and replaces emoji used as interface icons.",
 `<div class="grid f02">
  ${panel("Current set · rendered from assets/js/shared/icons.js", `<div class="igrid">${keys.map(k => `<div class="ig"><svg class="ic i24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS[k]}</svg><span>${k}</span></div>`).join("")}</div>`)}
  <div class="col g4">
   ${panel("Construction", `<div class="row g5" style="align-items:flex-end">${[16, 20, 24].map(s => `<div class="col" style="align-items:center"><div class="grid24" style="width:${s * 3}px;height:${s * 3}px">${I("groups").replace('class="ic "', `class="ic" style="width:${s * 3}px;height:${s * 3}px"`)}</div><span class="cap num">${s} px</span></div>`).join("")}</div>
    <ul class="rules sm"><li><b>16</b> inline with 12–13 px text, badges, help text</li><li><b>20</b> default: nav, buttons, inputs, list rows</li><li><b>24</b> tab bar, empty states, headers</li><li>Live area 18–20 px inside 24; optical centre, no fills except dots</li><li>Always <span class="mono">stroke="currentColor"</span>; colour comes from text token</li><li>Icon-only buttons need <span class="mono">aria-label</span>; decorative icons <span class="mono">aria-hidden</span></li></ul>`)}
   ${panel("Collisions fixed (proposed)", `<div class="fixes">
    <div class="fx"><div class="row g3">${I("settings".replace("settings", "sun"), "i24")}<span class="sup">vs current settings</span><span class="old">${typeof ICONS !== "undefined" ? `<svg class="ic i24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS.settings}</svg>` : ""}</span><span class="cap">look identical</span></div><div class="row g3">${I("back".replace("back", "chevR"), "i16")}<b class="sm">New “settings” (sliders)</b>${I("settings", "i24")}</div></div>
    <div class="fx"><div class="row g3"><b class="sm">Admin Rəy (Feedback)</b>${I("chat", "i24")}<span class="cap">= Çatlar</span>${I("chevR", "i16")}${I("inbox", "i24")}<span class="cap">use existing inbox</span></div></div>
    <div class="fx"><div class="row g3"><b class="sm">New glyphs</b>${["back", "swap", "x", "chevR", "chevD", "send", "more", "alert", "alertC", "filter", "wifiOff", "upload"].map(k => `<span class="ig sm2">${I(k, "i24")}<span>${k}</span></span>`).join("")}</div></div></div>`)}
   ${panel("Emoji used as interface icons → SVG", `<table class="tok">${EMOJI.map(([e, k, w]) => `<tr><td class="emo">${e}</td><td>${k === "—" ? `<span class="cap">—</span>` : I(k, "")}</td><td class="mono">${k}</td><td class="sec">${w}</td></tr>`).join("")}</table><p class="cap" style="margin-top:6px">Emoji remain only where they are user content: reactions, emoji picker, tag emoji typed by admins, message text.</p>`)}
  </div></div>`); };

/* =============== components =============== */
